description:
Write `sleep(ms, signal)` that returns a promise resolving after `ms` milliseconds, unless the optional `AbortSignal` aborts first:

- if the signal is already aborted, reject at once with `signal.reason`;
- if it aborts while waiting, clear the timer and reject with `signal.reason`;
- when the time passes normally, remove the abort listener and resolve.

starter.solution.js:
function sleep(ms, signal) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

solution.solution.js:
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal && signal.aborted) {
      reject(signal.reason);
      return;
    }
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason);
    };
    const timer = setTimeout(() => {
      if (signal) signal.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    if (signal) signal.addEventListener("abort", onAbort, { once: true });
  });
}

unitTests:
test("resolves after the time", async () => {
  const start = Date.now();
  await sleep(30);
  check(Date.now() - start >= 25);
});

test("rejects with the reason when aborted", async () => {
  const c = new AbortController();
  setTimeout(() => c.abort("stop"), 10);
  let reason = null;
  try {
    await sleep(1000, c.signal);
  } catch (e) {
    reason = e;
  }
  checkEq(reason, "stop");
});

test("already aborted rejects at once", async () => {
  const c = new AbortController();
  c.abort("early");
  let reason = null;
  const start = Date.now();
  try {
    await sleep(1000, c.signal);
  } catch (e) {
    reason = e;
  }
  checkEq(reason, "early");
  check(Date.now() - start < 100);
});

test("aborting after it finished does nothing", async () => {
  const c = new AbortController();
  await sleep(5, c.signal);
  c.abort("late");
  check(true);
});

